/* Site chat widget ("Chesky").
 *
 * Chesky answers from a stored knowledge base (js/chat-kb.js, generated by tools/kb.py): no live AI.
 * When he can't help, he offers to hand the chat to a person. The visitor leaves an email, the team
 * replies from /admin/, and the visitor sees the reply in this chat and also gets it by email.
 *
 * ENDPOINT (set in js/chat-config.js) is the deployed chat Worker (worker/chat). While it is empty the
 * handoff falls back to the visitor's email app, so nothing is ever lost.
 */
(() => {
  const ENDPOINT = (window.ES_CHAT_ENDPOINT || '').replace(/\/$/, '');
  const EMAIL = 'everythingshul@gmail.com';
  const KB = window.ES_KB;
  if (!KB) return;
  // Analytics: only topic ids and counts, never what the visitor typed.
  const T = (name, extra) => { try { if (window.esTrack) window.esTrack('ch', name, extra ? { x: extra } : undefined); } catch (e) { /* ignore */ } };

  const onHome = !!document.getElementById('work');
  const AVATAR = 'assets/chesky.svg';
  const TEAM_AVATAR = 'assets/favicon-32.png';
  const TEAM = 'Connect me with the team';
  const MAIN = ['What do you build?', 'Show me your work', 'How does it work?', TEAM];
  const STORE = 'es-chat-v2';
  const CONV = 'es-chat-conv';

  /* ====================================================================== matching engine */
  const SLANG = { u: 'you', ur: 'your', r: 'are', wat: 'what', wht: 'what', whts: "what's", hw: 'how', pls: 'please', plz: 'please', thx: 'thanks', abt: 'about', bc: 'because', cuz: 'because', w: 'with', y: 'why', k: 'ok', ya: 'you', yea: 'yeah', hav: 'have', dont: "don't", doesnt: "doesn't", cant: "can't", wont: "won't", isnt: "isn't", whats: "what's", hows: "how's", thats: "that's" };
  const norm = (s) => ' ' + String(s).toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[^a-z0-9'@.\-\s]/g, ' ')
    .replace(/\.(?=\s|$)/g, ' ')
    .replace(/(^|\s)[\-.']+(?=\s|$)/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ').map((w) => SLANG[w] || w).join(' ') + ' ';

  // Edit distance counting a swap of two neighbouring letters as one edit ("contcat" -> "contact").
  const lev = (a, b, max) => {
    if (Math.abs(a.length - b.length) > max) return max + 1;
    const d = [];
    for (let i = 0; i <= a.length; i++) { d.push([i]); }
    for (let j = 1; j <= b.length; j++) d[0][j] = j;
    for (let i = 1; i <= a.length; i++) {
      for (let j = 1; j <= b.length; j++) {
        const cost = a[i - 1] === b[j - 1] ? 0 : 1;
        d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
        if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
      }
    }
    return d[a.length][b.length];
  };

  // Pre-normalize every keyword once.
  const prep = (kws) => kws.map((k) => { const n = norm(k).trim(); return { n, phrase: n.includes(' '), words: n.split(' ').length }; });
  KB.entries.forEach((e) => { e._k = prep(e.k); e._n = (e.n || []).map((x) => norm(x)); });
  KB.pj.forEach((e) => { e._k = prep(e.k); });
  const aliasList = [];
  Object.keys(KB.aliases).forEach((id) => KB.aliases[id].forEach((a) => aliasList.push({ id, a: norm(a).trim() })));
  aliasList.sort((x, y) => y.a.length - x.a.length);

  // Light stemming so "websites" matches "website" and "technologies" matches "technology".
  const stem = (w) => (w.length > 4 && w.endsWith('ies') ? w.slice(0, -3) + 'y' : w.length > 3 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w);

  const scoreKw = (kws, t, tokens) => {
    let s = 0;
    const stems = tokens.map(stem);
    kws.forEach((k) => {
      if (!k.n) return;
      if (k.phrase) {
        if (t.includes(' ' + k.n + ' ')) s += 3 * k.words;
        else {
          const kp = k.n.split(' ').map(stem).join(' ');
          if ((' ' + stems.join(' ') + ' ').includes(' ' + kp + ' ')) s += 3 * k.words - 1;
        }
      } else if (tokens.includes(k.n) || stems.includes(stem(k.n))) {
        s += 3;
      } else if (k.n.length >= 6 && tokens.some((w) => w.length >= k.n.length && w.startsWith(k.n))) {
        s += 2;
      } else if (k.n.length >= 5) {
        const max = k.n.length >= 9 ? 2 : 1;
        if (tokens.some((w) => w.length >= 5 && lev(w, k.n, max) <= max)) s += 2;
      }
    });
    return s;
  };

  const bestEntry = (t, tokens) => {
    let best = null;
    KB.entries.forEach((e) => {
      if (e.s && tokens.length > 4) return;
      let s = scoreKw(e._k, t, tokens);
      if (s <= 0) return;
      if (e._n.some((x) => t.includes(x))) return;
      s += e.p || 0;
      if (!best || s > best.s) best = { e, s };
    });
    return best;
  };

  const bestPj = (t, tokens) => {
    let best = null;
    KB.pj.forEach((e) => {
      if (!e.k.length) return;
      const s = scoreKw(e._k, t, tokens);
      if (s > 0 && (!best || s > best.s)) best = { e, s };
    });
    return best;
  };

  const findProject = (t, tokens) => {
    for (const x of aliasList) {
      if (t.includes(' ' + x.a + ' ')) return x.id;
    }
    for (const x of aliasList) {
      if (!x.a.includes(' ') && x.a.length >= 5 && tokens.some((w) => w.length >= 5 && lev(w, x.a, 1) <= 1)) return x.id;
    }
    return null;
  };

  const pick = (r) => (Array.isArray(r) ? r[Math.floor(Math.random() * r.length)] : r);
  const fill = (tpl, id) => {
    const p = KB.projects[id];
    return tpl
      .replace(/\{name\}/g, p.name).replace(/\{kind\}/g, p.kind.toLowerCase()).replace(/\{desc\}/g, p.desc)
      .replace(/\{features\}/g, p.features.join(', ')).replace(/\{url\}/g, p.url).replace(/\{who\}/g, KB.who[id]);
  };

  /* ====================================================================== links, chips, replies */
  const hrefs = { contact: 'contact.html', mail: `mailto:${EMAIL}`, work: onHome ? '#work' : 'index.html#work', process: onHome ? '#process' : 'index.html#process', about: onHome ? '#about' : 'index.html#about', top: onHome ? '#top' : 'index.html' };
  const linkFor = (code) => {
    if (code.startsWith('p:')) { const id = code.slice(2); return { label: `See ${KB.projects[id].name} on this page`, href: onHome ? `#${id}` : `index.html#${id}` }; }
    if (code.startsWith('v:')) { const id = code.slice(2); return { label: `Visit ${KB.projects[id].name}`, href: KB.projects[id].url, external: true }; }
    const labels = { contact: 'Contact page', mail: EMAIL, work: 'Our work', process: 'See the process', about: 'About', top: 'Back to top' };
    return { label: labels[code], href: hrefs[code] };
  };
  const looksLikeOffer = (text) => /want me to (ask|pass)|connect you|pass (it|your)/i.test(text);

  const projectChips = (id) => {
    const n = KB.projects[id].name;
    return [`${n} features`, KB.tour[id] ? `Watch the ${n} tour` : `${n} pricing`, TEAM];
  };

  const fromEntry = (e, state) => {
    let text = pick(e.r);
    const m = { text, links: (e.l || []).map(linkFor), chips: e.c || [], action: e.a || null, entry: e.i, fb: e.f !== 0 && !['handoff', 'reset', 'repeat', 'recall', 'projects'].includes(e.a) };
    if (m.action === 'projects') m.chips = Object.keys(KB.projects).map((id) => KB.projects[id].name);
    if (m.action === 'repeat') {
      const last = [...state.history].reverse().find((x) => x.role === 'bot' && x.entry !== 'repeat');
      m.text = last ? last.text : 'Nothing to repeat yet. Ask me anything about Everything Shul!';
      m.chips = last && last.chips && last.chips.length ? last.chips : MAIN;
      m.links = last && last.links ? last.links : [];
    }
    if (m.action === 'recall') {
      const asked = state.history.filter((x) => x.role === 'user');
      const prev = asked[asked.length - 2];
      m.text = prev ? `You asked: \u201c${prev.text}\u201d` : "You haven't asked me anything yet!";
      m.action = null; m.fb = false; m.chips = MAIN;
    }
    if (m.action === 'offer' && !m.chips.length) m.chips = [TEAM, 'No thanks'];
    return m;
  };

  const fromProject = (intent, id) => {
    const P = KB.projects[id];
    const links = [linkFor(`p:${id}`), linkFor(`v:${id}`)];
    let text;
    switch (intent) {
      case 'tour':
        text = KB.tour[id]
          ? `Tap Watch full tour on the ${P.name} card for a walkthrough video with sound.`
          : `${P.name} has a scrolling preview on its card. For a live walkthrough, the team can arrange one. Want me to ask?`;
        break;
      case 'mobile':
        text = id === 'jlistings'
          ? `${P.name} is built mobile-first for browsing, so listings are easy to read on a phone.`
          : `I don't have details on how ${P.name} works on phones and tablets. The team can confirm. Want me to ask?`;
        break;
      case 'features':
        text = fill('What {name} includes: {features}.', id) + (KB.extra[id] ? ' ' + KB.extra[id] : '');
        break;
      default: {
        const tpl = (KB.pj.find((x) => x.j === intent) || KB.pj[0]).r;
        text = fill(tpl, id);
      }
    }
    return { text, links, chips: looksLikeOffer(text) ? [TEAM, 'No thanks'] : projectChips(id), action: looksLikeOffer(text) ? 'offer' : null, project: id, entry: 'pj:' + intent, fb: true };
  };

  const FALLBACK = [
    "I'm not sure I understood that one. Could you rephrase it, or I can connect you with the team?",
    "That's one I can't answer well. A real person can. Want me to connect you?",
    "Hmm, I don't have a good answer for that. Want to leave your question for the team?",
  ];
  const YES = /^\s*(yes|yeah|yep|yup|sure|ok|okay|please|yes please|go ahead|do it|sounds good|definitely|of course)\s*$/;

  const respond = (raw, state) => {
    const t = norm(raw);
    const tokens = t.trim().split(' ').filter(Boolean);

    // Answering "want me to pass that on?"
    if (state.pending === 'offer') {
      state.pending = null;
      if (YES.test(t)) return { text: 'Great, let me set that up.', action: 'handoff', chips: [], links: [] };
    }

    const explicit = findProject(t, tokens);
    const pid = explicit || (state.turnsSinceProject <= 3 ? state.project : null);
    const g = bestEntry(t, tokens);
    // For project intents, "who is JListings for" should read like "who is it for".
    let tp = t;
    if (explicit) aliasList.filter((x) => x.id === explicit).forEach((x) => { tp = tp.split(' ' + x.a + ' ').join(' it '); });
    const pj = bestPj(tp, tp.trim().split(' ').filter(Boolean));
    const gs = g ? g.s : 0;
    const ps = pj ? pj.s : 0;
    const shortMsg = tokens.length <= 3;

    if (explicit) {
      if (pj && ps >= 3 && (gs <= ps + 4 || (ps >= 6 && !(g && (g.e.p || 0) >= 3)))) return fromProject(pj.e.j, explicit);
      if (g && gs >= 3 && (gs > ps + 4 || ps < 3) && (g.e.p || 0) >= 2) return fromEntry(g.e, state);
      if (g && gs >= 9 && ps <= 3) return fromEntry(g.e, state);
      return fromProject('overview', explicit);
    }
    // Follow-up about the project we were just discussing ("how much does it cost?")
    if (pid && pj && (ps >= 6 || (shortMsg && ps >= 3) || (ps >= 3 && state.turnsSinceProject <= 1)) && (!g || (g.e.p || 0) < 2 || gs <= ps + 4)) {
      return fromProject(pj.e.j, pid);
    }
    if (g && gs >= 3) return fromEntry(g.e, state);
    return null;
  };


  /* ====================================================================== little tools */
  // Things Chesky can actually do, instead of deflecting: math, dates, dice, a few words of Hebrew/Yiddish.
  const rand = (n) => Math.floor(Math.random() * n);
  const fmtNum = (n) => { if (!isFinite(n)) return null; const r = Math.round(n * 1e10) / 1e10; return Math.abs(r) >= 1e15 ? r.toExponential(4) : String(r); };

  // Tiny recursive-descent calculator: + - * / % ^ and parentheses (no eval).
  const calc = (src) => {
    const s = src.replace(/\s+/g, '');
    let i = 0;
    const num = () => { const m = /^\d*\.?\d+/.exec(s.slice(i)); if (!m) throw new Error('num'); i += m[0].length; return parseFloat(m[0]); };
    const atom = () => {
      if (s[i] === '(') { i++; const v = expr(); if (s[i] !== ')') throw new Error('paren'); i++; return v; }
      if (s[i] === '-') { i++; return -atom(); }
      if (s[i] === '+') { i++; return atom(); }
      return num();
    };
    const pow = () => { const b = atom(); if (s[i] === '^') { i++; return Math.pow(b, pow()); } return b; };
    const term = () => { let v = pow(); while (s[i] === '*' || s[i] === '/' || s[i] === '%') { const op = s[i++]; const r = pow(); v = op === '*' ? v * r : op === '/' ? v / r : v % r; } return v; };
    const expr = () => { let v = term(); while (s[i] === '+' || s[i] === '-') { const op = s[i++]; const r = term(); v = op === '+' ? v + r : v - r; } return v; };
    const v = expr();
    if (i !== s.length) throw new Error('trailing');
    return v;
  };

  const mathReply = (raw) => {
    let q = String(raw).toLowerCase().replace(/×/g, '*').replace(/÷/g, '/').replace(/,(?=\d{3}\b)/g, '');
    const pct = /(\d+(?:\.\d+)?)\s*%\s*of\s*(\d+(?:\.\d+)?)/.exec(q);
    if (pct) return `${pct[1]}% of ${pct[2]} is ${fmtNum(parseFloat(pct[1]) * parseFloat(pct[2]) / 100)}.`;
    const sq = /square root of (\d+(?:\.\d+)?)/.exec(q);
    if (sq) return `The square root of ${sq[1]} is ${fmtNum(Math.sqrt(parseFloat(sq[1])))}.`;
    q = q.replace(/what(?:'s| is)|how much is|calculate|compute|solve|equals|what/g, ' ')
      .replace(/to the power of/g, '^').replace(/\bplus\b/g, '+').replace(/\bminus\b/g, '-')
      .replace(/\b(?:times|multiplied by)\b/g, '*').replace(/\b(?:divided by|over)\b/g, '/')
      .replace(/(\d)\s*x\s*(\d)/g, '$1*$2').replace(/[=?!]/g, ' ').trim();
    if (!/^[\d\s.+\-*/()^%]+$/.test(q) || !/\d/.test(q) || !/[+\-*/^%]/.test(q.replace(/^\s*[-+]/, ''))) return null;
    if (/^\d+\s*\/\s*\d+$/.test(q) && q.replace(/\s/g, '') === '24/7') return null;
    if (q.replace(/\D/g, '').length >= 14 || (/\d-\d/.test(q) && q.replace(/\D/g, '').length >= 8 && !/\s/.test(q))) return null;
    try {
      const v = calc(q);
      if (!isFinite(v)) return "That one doesn't work out, since you can't divide by zero.";
      const shown = q.replace(/\s+/g, '').replace(/([+\-*/^%])/g, ' $1 ').replace(/\s+/g, ' ').trim();
      return `${shown} = ${fmtNum(v)}`;
    } catch (e) { return null; }
  };

  const hebrewDate = () => {
    try { return new Intl.DateTimeFormat('en-u-ca-hebrew', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date()); } catch (e) { return null; }
  };

  const WORDS = {
    hello: ['shalom', 'sholem aleichem'], hi: ['shalom', 'sholem aleichem'], peace: ['shalom', 'sholem'],
    'thank you': ['toda', 'a dank'], thanks: ['toda', 'a dank'], 'thank you very much': ['toda raba', 'a sheynem dank'],
    'good morning': ['boker tov', 'a gutn morgn'], 'good night': ['laila tov', 'a gute nakht'], 'good evening': ['erev tov', 'a gutn ovnt'],
    please: ['bevakasha', 'zeyt azoy gut'], yes: ['ken', 'yo'], no: ['lo', 'neyn'], 'good luck': ['b\'hatzlacha', 'mazl un brokhe'],
    congratulations: ['mazal tov', 'mazl tov'], 'mazel tov': ['mazal tov', 'mazl tov'], 'mazal tov': ['mazal tov', 'mazl tov'], welcome: ['baruch haba', 'vilkum'],
    friend: ['chaver', 'fraynd'], love: ['ahava', 'libe'], water: ['mayim', 'vaser'], 'good week': ['shavua tov', 'a gute vokh'],
    'good shabbos': ['shabbat shalom', 'gut shabbos'], 'happy birthday': ['yom huledet sameach', 'a gutn geburtstog'], goodbye: ['lehitraot', 'zay gezunt'], sorry: ['slicha', 'zayt moykhl'],
  };
  const ALIAS_WORDS = { goodnight: 'good night', 'good morning to you': 'good morning', thx: 'thanks', 'thank u': 'thank you', 'mazel tov': 'congratulations', 'bye': 'goodbye', 'excuse me': 'sorry' };
  const translate = (phrase, lang) => {
    let w = phrase.toLowerCase().replace(/["'.!?]|the word|the phrase/g, '').replace(/\s+/g, ' ').trim();
    w = ALIAS_WORDS[w] || w;
    const hit = WORDS[w];
    if (!hit) return `I don't know that one yet. I only know a handful of words, like hello, thank you, good morning, please, yes, no, good luck, congratulations and welcome.`;
    const he = `Hebrew: "${hit[0]}"`; const yi = `Yiddish: "${hit[1]}"`;
    const out = lang === 'hebrew' ? he : lang === 'yiddish' ? yi : `${he}. ${yi}`;
    return `${w.charAt(0).toUpperCase() + w.slice(1)}. ${out}. (Spelling in English letters varies.)`;
  };

  const RPS = ['rock', 'paper', 'scissors'];
  const RPS_WIN = { rock: 'scissors', paper: 'rock', scissors: 'paper' };

  const utility = (raw, t, tokens) => {
    const has = (re) => re.test(t);
    const R = (text, chips) => ({ text, chips: chips || ['What do you build?', 'Tell me a joke', 'Fun fact', TEAM], links: [], entry: 'util', fb: false });

    const math = mathReply(raw);
    if (math) return R(math, ['Flip a coin', 'What do you build?', TEAM]);

    // Hebrew date (today's), but not questions about whether software supports it.
    if (has(/(what'?s|what is|tell me|give me)( the)?( today'?s)? (hebrew|jewish) (date|day)|today'?s (hebrew|jewish) date|(hebrew|jewish) date (today|now)|date in hebrew|which (hebrew|jewish) month|what (hebrew|jewish) month|what is the hebrew date/) && !has(/drm|software|platform|support|your|do you|can you|does /)) {
      const d = hebrewDate();
      if (d) return R(`By your device's date, it's ${d} on the Hebrew calendar. The Hebrew day actually begins at nightfall, so after dark it may already be the next date.`);
    }
    if (has(/what time is it|what'?s the time|what is the time|current time|the time now|tell me the time|do you have the time/)) {
      return R(`It's ${new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })} by your device's clock.`);
    }
    if (has(/today'?s date|what'?s the date|what is the date|what day is it|what day is today|what is today|what'?s today|current date|day of the week|what year is it|what month is it|what is the day today/)) {
      return R(`Today is ${new Date().toLocaleDateString([], { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}.`);
    }

    if (has(/flip (a )?coin|toss (a )?coin|coin flip|heads or tails|flip a coin/)) return R(`${pick(['Heads!', 'Tails!'])} Want another flip?`, ['Flip a coin', 'Roll a dice', 'What do you build?']);
    const die = /roll a d(\d+)/.exec(t);
    if (die || has(/roll (a |the )?(die|dice)|throw (a |the )?dice|dice roll|roll dice/)) {
      const sides = Math.min(1000, Math.max(2, die ? parseInt(die[1], 10) : 6));
      return R(`You rolled a ${1 + rand(sides)} (on a ${sides}-sided die).`, ['Roll a dice', 'Flip a coin', 'What do you build?']);
    }
    const rn = /(?:random number|pick a number|number)(?: between (\d+) and (\d+))?/.exec(t);
    if (rn && has(/random number|pick a number|number between \d+ and \d+/)) {
      let lo = rn[1] ? parseInt(rn[1], 10) : 1; let hi = rn[2] ? parseInt(rn[2], 10) : 100;
      if (lo > hi) [lo, hi] = [hi, lo];
      return R(`How about ${lo + rand(hi - lo + 1)}?`, ['Another number', 'Flip a coin', 'What do you build?']);
    }
    const rps = /^(?:i (?:choose|pick|play|go with|throw|say) )?(rock|paper|scissors)\b/.exec(t.trim());
    if (rps && tokens.length <= 5) {
      const me = RPS[rand(3)]; const you = rps[1];
      const res = me === you ? "It's a tie!" : RPS_WIN[you] === me ? 'You win!' : 'I win!';
      return R(`You chose ${you}, I chose ${me}. ${res}`, ['Rock', 'Paper', 'Scissors', 'What do you build?']);
    }
    const ch = /^(?:please |can you |could you )?(?:pick|choose|decide)(?: for me)?(?: between| one| from)?:?\s+(.+?)\??$/.exec(String(raw).toLowerCase().trim());
    if (ch) {
      const opts = ch[1].split(/\s+or\s+|,\s*|\s*\/\s*/).map((x) => x.replace(/^(?:one|between|from)\s+/, '').trim()).filter(Boolean);
      if (opts.length >= 2 && opts.length <= 6 && opts.every((o) => o.length <= 40)) return R(`I pick: ${pick(opts)}.`, ['Pick again', 'Flip a coin', 'What do you build?']);
    }
    if (/^pick again$/.test(t.trim())) return null;

    const tr = /(?:how (?:do|can|would) (?:you|i) say|what(?:'s| is)(?: the)?|translate|say)\s+(.+?)\s+(?:in|into|to)\s+(hebrew|yiddish)|^(.+?)\s+in\s+(hebrew|yiddish)\s*$/.exec(String(raw).toLowerCase().replace(/[?]+$/, '').trim());
    if (tr) return R(translate(tr[1] || tr[3], tr[2] || tr[4]), ['Thank you in Yiddish', 'Mazal tov in Hebrew', 'What do you build?']);
    return null;
  };

  const RANDOM_MISS = [
    "Good question, but it's outside my wheelhouse. I'm best with questions about Everything Shul, and I can't look things up. Want a joke or a fun fact instead?",
    "I wish I knew! That's beyond what I can answer here. I can tell you about our work, or pass anything to the team.",
    "That one's above my pay grade. I stick to Everything Shul questions, plus a few jokes and games on the side.",
    "Hmm, I don't have an answer for that, and I'd rather not guess. Ask me about our work, or try a joke or a game!",
  ];
  const ON_TOPIC = /\b(you|your|yours|we|our|us|shul|shuls|organi[sz]ations?|donors?|donations?|tickets?|platforms?|sites?|software|projects?|price|cost|team|help|build|built|custom|nonprofits?|charit(?:y|ies)|members?|events?|dinners?|fundrais\w*|apps?|systems?|database|website|email|contact|quote|support|developers?)\b/;
  const isRandomQuestion = (text) => { const t = norm(text); return t.trim().split(' ').length >= 3 && !ON_TOPIC.test(t); };

  /* ====================================================================== what the team has taught him */
  // Answers the team approved (from the admin page). Matched by how much of a question's meaning overlaps.
  const STOP = new Set(['a', 'an', 'the', 'is', 'are', 'am', 'was', 'were', 'be', 'do', 'does', 'did', 'you', 'your', 'yours', 'i', 'we', 'our', 'us', 'me', 'my', 'can', 'could', 'would', 'should', 'will', 'to', 'of', 'in', 'on', 'at', 'for', 'with', 'it', 'its', 'and', 'or', 'this', 'that', 'there', 'have', 'has', 'had', 'what', 'how', 'about', 'please', 'any', 'so', 'if', 'as', 'by', 'from', 'just', 'also', 'tell', 'know', 'want', 'need', 'get', 'got', 'like']);
  const contentTokens = (text) => norm(text).trim().split(' ').filter((w) => w && !STOP.has(w)).map(stem);
  let learned = [];
  const setLearned = (list) => {
    learned = (list || []).map((e) => ({ id: e.id, r: e.r, qs: (e.qs || []).map(contentTokens).filter((a) => a.length) }));
  };
  const sameWord = (a, b) => a === b || (a.length >= 5 && b.length >= 5 && lev(a, b, 1) <= 1);
  const learnedMatch = (t) => {
    if (!learned.length) return null;
    const B = contentTokens(t);
    if (!B.length) return null;
    let best = null;
    learned.forEach((e) => e.qs.forEach((A) => {
      const inter = A.filter((a) => B.some((b) => sameWord(a, b))).length;
      if (!inter) return;
      const sim = inter / (A.length + B.length - inter);
      const need = Math.min(2, A.length);
      if (inter >= need && sim >= 0.6 && (!best || sim > best.sim)) best = { e, sim };
    }));
    return best;
  };
  const LKEY = 'es-chat-learned';
  const loadLearned = async () => {
    if (!ENDPOINT) return;
    try {
      const cached = JSON.parse(ssGet(LKEY) || 'null');
      if (cached && Date.now() - cached.at < 10 * 60 * 1000) { setLearned(cached.entries); return; }
    } catch (e) { /* ignore */ }
    try {
      const res = await fetch(`${ENDPOINT}/learned`);
      if (!res.ok) return;
      const data = await res.json();
      setLearned(data.entries);
      ssSet(LKEY, JSON.stringify({ at: Date.now(), entries: data.entries }));
    } catch (e) { /* offline: the built-in answers still work */ }
  };

  // Anonymous signals so the team can see what he can't answer: never names or emails.
  const logEvent = (type, q, entry) => {
    if (!ENDPOINT || !q) return;
    try {
      fetch(`${ENDPOINT}/log`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ type, q: String(q).slice(0, 200), entry: entry || '' }), keepalive: true }).catch(() => {});
    } catch (e) { /* ignore */ }
  };

  const respondAll = (raw, state) => {
    const t = norm(raw);
    const tokens = t.trim().split(' ').filter(Boolean);
    if (!(state.pending === 'offer' && YES.test(t))) {
      const u = utility(raw, t, tokens);
      if (u) { state.pending = null; return u; }
      const L = learnedMatch(t);
      if (L) { state.pending = null; return { text: L.e.r, links: [], chips: ['What do you build?', TEAM], entry: 'L:' + L.e.id, fb: true }; }
    }
    return respond(raw, state);
  };

  if (window.ES_CHAT_DEBUG) window.__chat = { respond: respondAll, norm, setLearned };


  /* ====================================================================== state */
  const state = { history: [], pending: null, project: null, turnsSinceProject: 99, misses: 0, randoms: 0 };
  let human = null; // { id, known }
  const ssGet = (k) => { try { return sessionStorage.getItem(k); } catch (e) { return null; } };
  const ssSet = (k, v) => { try { sessionStorage.setItem(k, v); } catch (e) { /* ignore */ } };
  const lsGet = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };
  const lsSet = (k, v) => { try { v == null ? localStorage.removeItem(k) : localStorage.setItem(k, v); } catch (e) { /* ignore */ } };
  try { state.history = JSON.parse(ssGet(STORE) || '[]'); } catch (e) { state.history = []; }
  const save = () => { if (!human) ssSet(STORE, JSON.stringify(state.history.filter((m) => !m.form).slice(-30))); };

  /* ====================================================================== DOM */
  const el = (tag, cls, html) => { const n = document.createElement(tag); if (cls) n.className = cls; if (html != null) n.innerHTML = html; return n; };
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const autolink = (s) => esc(s)
    .replace(/(https?:\/\/[^\s<]+[^\s<.,;:!?)])/g, '<a href="$1" target="_blank" rel="noopener">$1</a>')
    .replace(/([\w.+-]+@[\w-]+\.[\w.]+[\w])/g, '<a href="mailto:$1">$1</a>')
    .replace(/\n/g, '<br>');

  const fab = el('button', 'chat-fab',
    '<span class="chat-fab-ring"></span>' +
    `<img class="chat-face" src="${AVATAR}" alt="" width="58" height="58">` +
    '<span class="chat-badge"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/></svg></span>' +
    '<span class="chat-unread" hidden>1</span>' +
    '<svg class="chat-ico-close" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>');
  fab.type = 'button';
  fab.setAttribute('aria-label', 'Chat with Chesky');
  fab.setAttribute('aria-expanded', 'false');

  const nudge = el('div', 'chat-nudge', "Hi, I'm Chesky. Ask me anything!");
  const panel = el('section', 'chat-panel');
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-label', 'Chat with Chesky');
  panel.innerHTML =
    `<header class="chat-head"><img src="${AVATAR}" alt="" width="38" height="38"><div><strong>Chesky</strong><span><i></i><em>Online</em></span></div>` +
    '<button type="button" class="chat-x" aria-label="Close chat">×</button></header>' +
    '<div class="chat-log" aria-live="polite"></div>' +
    '<div class="chat-chips"></div>' +
    '<form class="chat-form"><input type="text" maxlength="500" placeholder="Type your question…" aria-label="Your message" autocomplete="off"><button type="submit" aria-label="Send"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button></form>';
  document.body.append(panel, nudge, fab);

  const log = panel.querySelector('.chat-log');
  const chipsBox = panel.querySelector('.chat-chips');
  const form = panel.querySelector('.chat-form');
  const input = form.querySelector('input');
  const headName = panel.querySelector('.chat-head strong');
  const headSub = panel.querySelector('.chat-head em');
  const headImg = panel.querySelector('.chat-head img');
  const unread = fab.querySelector('.chat-unread');

  const scroll = () => { log.scrollTop = log.scrollHeight; };

  const addLinks = (body, links) => {
    if (!links || !links.length) return;
    const wrap = el('div', 'chat-links');
    links.forEach((l) => {
      const a = el('a', 'chat-link', esc(l.label) + (l.external ? ' ↗' : ''));
      a.href = l.href;
      if (l.external) { a.target = '_blank'; a.rel = 'noopener'; }
      if (l.href.startsWith('#')) {
        a.addEventListener('click', (ev) => {
          if (l.href === '#top') { ev.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
          close();
        });
      }
      wrap.appendChild(a);
    });
    body.appendChild(wrap);
  };

  const addMessage = (m, animate = true) => {
    if (m.form) return addForm(m);
    const role = m.role === 'user' ? 'user' : m.role === 'team' ? 'team' : m.role === 'system' ? 'system' : 'bot';
    const row = el('div', `chat-msg ${role}${animate ? ' pop' : ''}`);
    if (role === 'system') {
      row.appendChild(el('div', 'chat-sys', esc(m.text)));
      log.appendChild(row); scroll(); return row;
    }
    const bubble = el('div', 'chat-bubble', role === 'user' ? esc(m.text) : autolink(m.text));
    let body = row;
    if (role !== 'user') {
      const av = el('img', 'chat-av');
      av.src = role === 'team' ? TEAM_AVATAR : AVATAR;
      av.alt = '';
      row.appendChild(av);
      body = el('div', 'chat-body');
      row.appendChild(body);
      if (role === 'team') body.appendChild(el('span', 'chat-who', 'Everything Shul team'));
    }
    body.appendChild(bubble);
    addLinks(body, m.links);
    if (role === 'bot' && m.fb && animate) {
      log.querySelectorAll('.chat-fb').forEach((x) => x.remove());
      const fb = el('div', 'chat-fb',
        '<button type="button" data-k="up" aria-label="This helped"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 11v9H4v-9h3zM7 11l4-8c1.5 0 2.5 1 2.5 2.5V9H19a2 2 0 0 1 2 2.3l-1 6A2 2 0 0 1 18 19H7"/></svg></button>' +
        '<button type="button" data-k="down" aria-label="This did not help"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17 13V4h3v9h-3zM17 13l-4 8c-1.5 0-2.5-1-2.5-2.5V15H5a2 2 0 0 1-2-2.3l1-6A2 2 0 0 1 6 5h11"/></svg></button>');
      fb.querySelectorAll('button').forEach((btn) => btn.addEventListener('click', () => onFeedback(m, btn.dataset.k, fb)));
      body.appendChild(fb);
    }
    log.appendChild(row);
    scroll();
    return row;
  };

  // Thumbs: tell the team how an answer landed so they can fix or teach it.
  const onFeedback = (m, kind, fb) => {
    logEvent(kind, m.q || '', m.entry || '');
    T(kind, { e: m.entry || '' });
    fb.innerHTML = `<span class="chat-fb-done">${kind === 'up' ? 'Glad that helped!' : 'Thanks, I noted that.'}</span>`;
    if (kind === 'down') {
      const msg = { role: 'bot', text: "Sorry about that. Want me to pass your question to the team? They can answer it properly, and it helps them teach me for next time.", chips: [TEAM, 'No thanks'], links: [] };
      state.history.push(msg); addMessage(msg); setChips(msg.chips); state.pending = 'offer'; save();
    }
  };

  const setChips = (chips) => {
    chipsBox.innerHTML = '';
    (chips || []).forEach((c, i) => {
      const b = el('button', 'chat-chip', esc(c));
      b.type = 'button';
      b.style.setProperty('--i', i);
      b.addEventListener('click', () => ask(c));
      chipsBox.appendChild(b);
    });
    requestAnimationFrame(scroll);
  };

  const typing = () => {
    const row = el('div', 'chat-msg bot pop typing', `<img class="chat-av" src="${AVATAR}" alt=""><div class="chat-body"><div class="chat-bubble"><span></span><span></span><span></span></div></div>`);
    log.appendChild(row);
    scroll();
    return row;
  };

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  /* ====================================================================== handoff form */
  const validEmail = (s) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);

  const transcript = () => state.history.filter((m) => !m.form && m.text).slice(-14)
    .map((m) => ({ role: m.role === 'user' ? 'customer' : 'bot', text: m.text }));

  function addForm(m) {
    const lastQ = [...state.history].reverse().find((x) => x.role === 'user');
    const row = el('div', 'chat-msg bot pop formrow');
    row.appendChild(Object.assign(el('img', 'chat-av'), { src: AVATAR, alt: '' }));
    const body = el('div', 'chat-body');
    const f = el('form', 'chat-handoff');
    f.noValidate = true;
    f.innerHTML =
      '<label>Your email<input type="email" name="email" required maxlength="200" autocomplete="email" placeholder="you@example.com"></label>' +
      '<label>Your name <small>(optional)</small><input type="text" name="name" maxlength="120" autocomplete="name"></label>' +
      '<label>What would you like to ask?<textarea name="message" required maxlength="1500" rows="2" placeholder="Tell the team what you need"></textarea></label>' +
      '<p class="chat-form-note">The team replies here in the chat and to your email.</p>' +
      '<p class="chat-form-err" role="alert"></p>' +
      '<div class="chat-form-actions"><button type="submit" class="chat-send">Send to the team</button><button type="button" class="chat-cancel">Cancel</button></div>';
    f.elements.message.value = lastQ ? lastQ.text : '';
    f.elements.email.value = lsGet('es-chat-email') || '';
    body.appendChild(f);
    row.appendChild(body);
    log.appendChild(row);
    setChips([]);
    requestAnimationFrame(() => { log.scrollTop = Math.max(0, row.offsetTop - 10); });
    setTimeout(() => (f.elements.email.value ? f.elements.message : f.elements.email).focus({ preventScroll: true }), 250);

    f.querySelector('.chat-cancel').addEventListener('click', () => {
      row.remove();
      const msg = { role: 'bot', text: 'No problem. Anything else I can help with?', chips: MAIN, links: [] };
      state.history.push(msg); addMessage(msg); setChips(msg.chips); save();
    });

    f.addEventListener('submit', async (ev) => {
      ev.preventDefault();
      const err = f.querySelector('.chat-form-err');
      err.textContent = '';
      const email = f.elements.email.value.trim();
      const message = f.elements.message.value.trim();
      const name = f.elements.name.value.trim();
      if (!validEmail(email)) { err.textContent = 'Please enter a valid email so the team can reply.'; return; }
      if (!message) { err.textContent = 'Please add a short message.'; return; }
      const btn = f.querySelector('.chat-send');
      btn.disabled = true; btn.textContent = 'Sending…';
      lsSet('es-chat-email', email);

      if (!ENDPOINT) {
        // No chat server yet: hand the message to the visitor's email app.
        const lines = transcript().map((x) => `${x.role === 'customer' ? 'Me' : 'Chesky'}: ${x.text}`).join('\n');
        const body = `${message}\n\n${name ? 'Name: ' + name + '\n' : ''}Email: ${email}\n\n--- chat so far ---\n${lines}`;
        window.location.href = `mailto:${EMAIL}?subject=${encodeURIComponent('Question from the website chat')}&body=${encodeURIComponent(body)}`;
        row.remove();
        const msg = { role: 'bot', text: `I've opened your email app with your message addressed to the team. If nothing opened, write to ${EMAIL}.`, chips: MAIN, links: [] };
        state.history.push(msg); addMessage(msg); setChips(msg.chips); save();
        return;
      }
      try {
        const res = await fetch(`${ENDPOINT}/handoff`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name, email, message, transcript: transcript(), page: location.pathname }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.id) throw new Error(data.error || 'failed');
        lsSet(CONV, data.id);
        T('handoff');
        row.remove();
        enterHumanMode({ id: data.id, known: data.count || 0 });
        const total = state.history.length;
        const msg = { role: 'bot', text: `Thanks${name ? ', ' + name.split(' ')[0] : ''}! Your message is with the team. They'll reply right here and by email at ${email}. You can close this chat; any reply will be waiting when you come back.`, links: [] };
        state.history.push(msg); addMessage(msg); save();
        void total;
      } catch (e) {
        btn.disabled = false; btn.textContent = 'Send to the team';
        err.innerHTML = `Sorry, that didn't go through. Please try again, or email <a href="mailto:${EMAIL}">${EMAIL}</a>.`;
      }
    });
  }

  /* ====================================================================== human mode */
  let pollTimer = null;
  const showUnread = (n) => { unread.hidden = !n; unread.textContent = n > 9 ? '9+' : String(n); };
  let unreadCount = 0;

  const setHumanUI = (on) => {
    panel.classList.toggle('human', on);
    headName.textContent = on ? 'Everything Shul team' : 'Chesky';
    headSub.textContent = on ? 'Replies here and by email' : 'Online';
    headImg.src = on ? TEAM_AVATAR : AVATAR;
    input.placeholder = on ? 'Message the team…' : 'Type your question…';
  };

  function enterHumanMode(h) {
    human = h;
    setHumanUI(true);
    setChips([]);
    startPolling();
  }

  function leaveHumanMode() {
    human = null;
    lsSet(CONV, null);
    setHumanUI(false);
    if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    state.history = [];
    state.pending = null;
  }

  const renderServer = (m) => {
    const role = m.from === 'customer' ? 'user' : m.from === 'admin' ? 'team' : m.from === 'system' ? 'system' : 'bot';
    return { role, text: m.text, links: [] };
  };

  const poll = async (initial = false) => {
    if (!human || !ENDPOINT) return;
    try {
      const res = await fetch(`${ENDPOINT}/poll?id=${encodeURIComponent(human.id)}&after=${human.known}`);
      if (res.status === 404) { if (initial) { leaveHumanMode(); } return; }
      if (!res.ok) return;
      const data = await res.json();
      let fresh = 0;
      (data.messages || []).forEach((m) => {
        const r = renderServer(m);
        state.history.push(r);
        addMessage(r, !initial);
        if (r.role === 'team') fresh++;
      });
      human.known = data.total != null ? data.total : human.known + (data.messages || []).length;
      if (fresh && !isOpen) { unreadCount += fresh; showUnread(unreadCount); nudge.textContent = 'New reply from the team'; nudge.classList.add('show'); }
      if (data.status === 'closed') {
        addMessage({ role: 'system', text: 'The team closed this conversation. Start a new chat anytime.' });
        leaveHumanMode();
        setTimeout(() => { const msg = { role: 'bot', text: 'Anything else I can help with?', chips: MAIN, links: [] }; state.history.push(msg); addMessage(msg); setChips(MAIN); save(); }, 600);
      }
    } catch (e) { /* offline: try again next tick */ }
  };

  function startPolling() {
    if (pollTimer) clearInterval(pollTimer);
    let n = 0;
    pollTimer = setInterval(() => { n++; if (isOpen || n % 5 === 0) poll(); }, 6000);
  }

  const sendToTeam = async (text) => {
    const m = { role: 'user', text };
    state.history.push(m);
    addMessage(m);
    try {
      const res = await fetch(`${ENDPOINT}/send`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: human.id, text }),
      });
      if (res.status === 409 || res.status === 404) {
        addMessage({ role: 'system', text: 'This conversation has ended. Start a new chat anytime.' });
        leaveHumanMode();
        const msg = { role: 'bot', text: 'Anything else I can help with?', chips: MAIN, links: [] };
        state.history.push(msg); addMessage(msg); setChips(MAIN);
        return;
      }
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error('failed');
      if (data.count != null) human.known = data.count;
    } catch (e) {
      addMessage({ role: 'system', text: "That didn't send. Check your connection and try again." });
    }
  };

  /* ====================================================================== asking */
  let busy = false;

  async function ask(text) {
    text = text.trim();
    if (!text || busy) return;
    input.value = '';
    if (human) { T('human'); await sendToTeam(text); return; }
    T('send');
    busy = true;
    setChips([]);
    log.querySelectorAll('.chat-fb').forEach((x) => x.remove());
    const q = { role: 'user', text };
    state.history.push(q);
    addMessage(q);
    const t = typing();
    const started = Date.now();

    let reply = respondAll(text, state);
    if (reply) {
      if (reply.entry === 'util') T('tool'); else T('match', { e: reply.entry || 'other' });
    } else if (isRandomQuestion(text)) {
      T('match', { e: 'random' });
    } else {
      T('miss');
    }
    if (reply) {
      state.misses = 0; state.randoms = 0;
      if (reply.project) { state.project = reply.project; state.turnsSinceProject = 0; } else { state.turnsSinceProject++; }
    } else if (isRandomQuestion(text)) {
      // A random question that has nothing to do with us: friendly, and not a "failure".
      state.turnsSinceProject++;
      state.randoms++;
      reply = state.randoms >= 3
        ? { text: "I'm clearly not hitting the mark today. Want me to bring in a real person from the team?", chips: [TEAM, 'No thanks'], links: [], action: 'offer' }
        : { text: pick(RANDOM_MISS), chips: ['Tell me a joke', 'Fun fact', 'What do you build?', TEAM], links: [], action: null };
    } else {
      state.misses++;
      state.turnsSinceProject++;
      if (text.split(/\s+/).length >= 2 || text.length >= 5) logEvent('miss', text, '');
      if (state.misses >= 2) {
        reply = { text: "I'm still not getting it, and I don't want to waste your time. Let me pass this to a real person.", action: 'handoff', chips: [], links: [] };
      } else {
        reply = { text: pick(FALLBACK), action: 'offer', chips: [TEAM, 'What do you build?', 'Show me your work'], links: [] };
      }
    }
    await sleep(Math.max(0, 600 - (Date.now() - started)));
    t.remove();

    if (reply.action === 'reset') {
      state.history = []; log.innerHTML = ''; state.project = null; state.pending = null; state.misses = 0;
    }
    const m = { role: 'bot', text: reply.text, links: reply.links || [], chips: reply.chips || [], entry: reply.entry, q: text, fb: !!reply.fb };
    state.history.push(m);
    addMessage(m);
    state.pending = reply.action === 'offer' ? 'offer' : null;
    if (reply.action === 'offer' || reply.action === 'handoff') T('offer');
    if (reply.action === 'handoff') {
      if (!ENDPOINT && !EMAIL) { /* unreachable */ }
      addMessage({ form: true });
    } else {
      setChips(m.chips);
    }
    save();
    busy = false;
    input.focus({ preventScroll: true });
  }

  form.addEventListener('submit', (e) => { e.preventDefault(); ask(input.value); });

  /* ====================================================================== open / close */
  let isOpen = false;
  const open = () => {
    if (!isOpen) T('open');
    isOpen = true;
    panel.classList.add('open');
    fab.classList.add('open');
    fab.setAttribute('aria-expanded', 'true');
    fab.setAttribute('aria-label', 'Close chat');
    nudge.classList.remove('show');
    unreadCount = 0; showUnread(0);
    ssSet(STORE + '-nudged', '1');
    if (human) poll();
    if (!state.history.length) {
      const hello = { role: 'bot', text: "Hi, I'm Chesky! I can tell you about the platforms we've built, how we work, or put you in touch with the team.", links: [], chips: MAIN };
      state.history.push(hello);
      addMessage(hello);
      setChips(hello.chips);
      save();
    }
    setTimeout(() => input.focus({ preventScroll: true }), 250);
  };
  function close() {
    isOpen = false;
    panel.classList.remove('open');
    fab.classList.remove('open');
    fab.setAttribute('aria-expanded', 'false');
    fab.setAttribute('aria-label', 'Chat with Chesky');
  }

  fab.addEventListener('click', () => (isOpen ? close() : open()));
  panel.querySelector('.chat-x').addEventListener('click', close);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && isOpen) { close(); fab.focus(); } });
  nudge.addEventListener('click', open);

  /* ====================================================================== start up */
  // Link from a reply email: .../#chat=<id>
  const m = /[#&]chat=([\w-]{16,})/.exec(location.hash);
  if (m) {
    lsSet(CONV, m[1]);
    history.replaceState(null, '', location.pathname + location.search);
    setTimeout(open, 400);
  }

  const savedConv = lsGet(CONV);
  if (savedConv && ENDPOINT) {
    human = { id: savedConv, known: 0 };
    setHumanUI(true);
    state.history = [];
    poll(true).then(() => { if (human) startPolling(); });
  } else {
    state.history.forEach((x) => addMessage(x, false));
    if (state.history.length) setChips(state.history[state.history.length - 1].chips || []);
  }

  loadLearned();

  const nudged = ssGet(STORE + '-nudged');
  if (!nudged && !m) setTimeout(() => { if (!isOpen) nudge.classList.add('show'); }, 7000);
})();
